mapper.select:
SELECT id,node_codes,scheduled_at,attempts
FROM reminder_dispatch_attempt
WHERE attempts < #{maxAttempts}
  AND scheduled_at >= #{todayStart}
  AND (
        (next_retry_at IS NOT NULL AND next_retry_at <= #{now}
         AND (status='FAILED' OR unresolved_count > 0))
     OR (status='RUNNING' AND started_at <= #{staleBefore})
  )
ORDER BY scheduled_at,id
LIMIT 20

SELECT COUNT(1)
FROM reminder_dispatch_attempt
WHERE node_codes=#{nodeCodes}
  AND scheduled_at > #{scheduledAt}
  AND scheduled_at >= #{todayStart}

mapper.delete:
DELETE FROM reminder_dispatch_attempt
WHERE scheduled_at <= #{scheduledBefore}
LIMIT #{limit}

mapper.select:
SELECT COUNT(1)
FROM reminder_dispatch_attempt
WHERE scheduled_at <= #{scheduledBefore}
